/*
 * Script Name:	ImportDataBricksConnectors
 * Author:		J. de Baat
 * Purpose:		Import the Connector information from DataBricks CSV file into the repository using the BaatScriptLib scripts
 * Date:		20-12-2024
 * 
 */

const CSVFilterString        = "CSV Files (*.csv;*.txt)|*.csv;*.txt|All Files (*.*)|*.*||";

// The level to log at
var   BLOGLEVEL = BLOGLEVEL_WARNING;		// Choose from: BLOGLEVEL_ERROR, BLOGLEVEL_WARNING, BLOGLEVEL_INFO, BLOGLEVEL_DEBUG, BLOGLEVEL_TRACE

let   intImportRowNr = 0;
let   intShowDelta   = 10;
let   intShowRowNr   = 0;

/*
 * Handle the CSVImport for importing Connectors
 */
function IDBImportConnectors( )
{

	try {

		// Clear the cache before importing starts
		IDBElementCacheMap  = null;					// : Map   cache for IDBElements
		IDBElementCacheList = null;					// : Array cache for IDBElements

		// Get the CSV fileName for this Import session, true for readonly.
		let curCSVFileName = DLGOpenFile( CSVFilterString, 1 );
		if ( ( curCSVFileName == null ) || ( curCSVFileName == "" ) ) {
			BLOGError( "DLGOpenFile could NOT Get curCSVFileName!" );
			return " IDBImportConnectors DLGOpenFile could NOT Get curCSVFileName!!!";
		}
		strImExSource = ImExSourceCSV;

		// Start the CSVImport for this session
		Session.Output( _BLOGGetDisplayDate() + " IDBImportConnectors started CSV Import for curCSVFileName " + curCSVFileName + "!!!" );
		CSVIImportFile( curCSVFileName, true );

		// Clear the cache after importing finished
		IDBElementCacheMap  = null;					// : Map   cache for IDBElements
		IDBElementCacheList = null;					// : Array cache for IDBElements

		// Return "" as successful result
		return "";

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
		return "IDBImportConnectors catched error " + catch_err.message + "!";
	}

}

/*
 * Process the Connectors found in the CSV Import file
 */
function OnRowImported( theRow )
{

	var curConnector as EA.Connector;

	let importRow = 0;

	try {

		importRow = importCurrentRow;
		intImportRowNr++;
		strMessage = "Processing importCurrentRow(" + importRow + ").length = " + importCurrentRow.length + ", [0] = " + importCurrentRow[0] + "!!!";
		BLOGTrace( strMessage );

		// Find and process the Connectors available in this importRow
		curConnector = IDBFindConnector( ImExColumnConnectorGUID, IDBTaggedValueIDBKey );
		if ( curConnector != null ) {
			// Process Connector found
			strMessage = "Found curConnector.Name = " + curConnector.Name + ", ConnectorID = " + curConnector.ConnectorID + ", ClientID = " + curConnector.ClientID + ", SupplierID = " + curConnector.SupplierID + "!!!";
			BLOGTrace( strMessage );
		} else {
			// Connector NOT found so create new Connector
			BLOGTrace("Needs to create new curConnector!!!" );
			curConnector = IDBCreateConnector();
		}

		// Process the ConnectorProperties
		if ( curConnector != null ) {
			BLOGTrace("Created curConnector.Name = " + curConnector.Name + ", ConnectorID = " + curConnector.ConnectorID + ", ClientID = " + curConnector.ClientID + ", SupplierID = " + curConnector.SupplierID + "!!!" );

			// Process the updates for curConnector found
			let curResult = IDBUpdateConnectorProperties( curConnector );
			strMessage = "Updated[ " + importRow + " ] Properties of ConnectorID " + curConnector.ConnectorID + ", curResult= " + curResult + "!!!";
			BLOGTrace( strMessage );

			// Only show progress for each intShowDelta Elements
			if ( intImportRowNr >= intShowRowNr ) {
				strMessage = _BLOGGetDisplayDate() + " Processed row[ " + intImportRowNr + " ] for ConnectorID " + curConnector.ConnectorID + ", curResult = "  + curResult + "!";
				Session.Output( strMessage );
				intShowRowNr += intShowDelta;
			}
		} else {
			strMessage = _BLOGGetDisplayDate() + "Processed row[ " + intImportRowNr + " ] for null curConnector!";
			Session.Output( strMessage );
		}

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
	}

	// Free up memory
	curElement        = null;
	currentLine       = null;
	currentLineTokens = null;
}

/*
 * Create theConnector with information as provided
 */
function IDBCreateConnector()
{

	var curConnector       as EA.Connector;
	var curElementClient   as EA.Element;
	var curElementSupplier as EA.Element;

	curConnector            = null;

	try {

		// Find and process the source element defined by CSO_CLASSGUID or IDBTaggedValueIDBSource
		let curElementClient = IDBFindElement( ImExColumnCSOClassGUID, IDBTaggedValueIDBSource );
		if ( curElementClient == null ) {
			BLOGWarning("Could NOT find curElementClient so skip creation!!!");
			return null;
		}

		// Find and process the source element defined by CTO_CLASSGUID or IDBTaggedValueIDBTarget
		let curElementSupplier = IDBFindElement( ImExColumnCTOClassGUID, IDBTaggedValueIDBTarget );
		if ( curElementSupplier == null ) {
			BLOGWarning("Could NOT find curElementSupplier so skip creation!!!");
			return null;
		}

		// Create newConnector
		let curConnectorType = IDBIGetColumnValueByName( ImExColumnConnectorType );
		if ( curConnectorType == null ) {
			curConnectorType = ConnectorStereotypeDefault;
			BLOGTrace("Could NOT find curConnectorType so set to default: " + curConnectorType + " !!!");
		}
		BLOGTrace("Create new curConnector with Connector_Type " + curConnectorType + " for curElementClient " + curElementClient.Name + " and curElementSupplier = " + curElementSupplier.Name + "!!!" );
		curConnector = CONSetElementConnector( curElementClient, curElementSupplier, curConnectorType, true );

		// IDBCreateConnector created new curConnector so update it using the other values found
		if ( curConnector != null ) {

			// Set the curConnector Direction as Source -> Destination
			curConnector.ClientEnd.IsNavigable = false;
			curConnector.ClientEnd.Update();
			curConnector.SupplierEnd.IsNavigable = true;
			curConnector.SupplierEnd.Update();
			curConnector.Update();

			// Process the Properties for curConnector found
			curConnector.RouteStyle = ConnectorRouteStyleDefault;
			curConnector.Stereotype = ConnectorStereotypeDefault;
			curConnector.ClientEnd.Aggregation = ConnectorArchiMateAssociation;

			curConnector.Update();

		} else {

			strMessage = "Could NOT create curConnector for curElementClient " + curElementClient.Name + " and curElementSupplier = " + curElementSupplier.Name + " so NOT updated!!!";
			BLOGWarning( strMessage );
			return null;
		}

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
	}

	return curConnector;
}

/*
 * Update theConnector with information as provided in the fields
 */
function IDBUpdateConnectorProperties( theConnector )
{

	// Cast theConnector to EA.Connector so we get intellisense
	var curConnector     as EA.Connector;
	curConnector          = theConnector;

	try {

		// Process theConnector
		if ( curConnector != null ) {

			BLOGTrace("( " + curConnector.ConnectorGUID + " ) found curConnector.ConnectorID = " + curConnector.ConnectorID + "!!!" );

			// Process StandardConnectorTaggedValues
			IDBISetConnectorTaggedValues( curConnector );
			BLOGTrace("( " + curConnector.ConnectorGUID + " ) updated curConnector.ConnectorID to " + curConnector.ConnectorID + ", #curConnectorTags = " + curConnector.TaggedValues.Count + "!!!" );

			// Add TaggedValues to the curConnector
			TVSetElementTaggedValue( curConnector, IDBTaggedValueIDBProcessed,   _BLOGGetDisplayDate(),    true );
			TVSetElementTaggedValue( curConnector, IDBTaggedValueIDBConnectorID, curConnector.ConnectorID, true );
			TVSetElementTaggedValue( curConnector, IDBTaggedValueIDBSourceID,    curConnector.ClientID,    true );
			TVSetElementTaggedValue( curConnector, IDBTaggedValueIDBTargetID,    curConnector.SupplierID,  true );
			BLOGTrace("( " + curConnector.ConnectorGUID + " ) added TaggedValues " + IDBTaggedValueIDBProcessed + " ( " + _BLOGGetDisplayDate() + " ), " + IDBTaggedValueIDBSource + " ( " + curConnector.ClientID + " )!!!" );

			// Commit the changes to the repository
			objGlobalIDBPackage.Update();
			objGlobalIDBPackage.Connectors.Refresh();

		} else {

			return "Could NOT find curConnector so NOT updated!!!";
		}

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
		return "IDBUpdateConnectorProperties catched error " + catch_err.message + "!";
	}

	return "";
}

/*
 * Diagram Script main function
 */
function ImportDataBricksConnectors()
{
	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );

	Session.Output( "======================================= Started ImportDataBricksConnectors at " + _BLOGGetDisplayDate() + "!" );

	try
	{

		// Get and check the global variables
		const validDiagram = IDBGetAndCheckDiagram();
		if ( validDiagram ) {
			BLOGInfo( "Diagram is VALID so proceed processing!" );
			strImExStart       = strImExStartDiagram;
			objGlobalEADiagram = objGlobalIDBDiagram;

			let curResult = IDBImportConnectors();
			if ( curResult.length > 0 ) {
				BLOGError( curResult );
			} else {
				BLOGInfo( "Finished processing!" );
			}

			// Refresh the objGlobalIDBDiagram using ReloadDiagram
			objGlobalIDBDiagram.Update();
			Repository.ReloadDiagram( objGlobalIDBDiagram.DiagramID );

		} else {
			BLOGError( "Diagram is NOT VALID!" );
		}
	}
	catch(catch_err)
	{
		BLOGError(" found Error: " + catch_err + "!!!" );
	}

	Session.Output( "======================================= Finished ImportDataBricksConnectors at " + _BLOGGetDisplayDate() + "!" );
}

ImportDataBricksConnectors();

//[group=BaatDiagramScripts]
!INC Local Scripts.EAConstants-JavaScript
!INC BaatScriptLib.BaatScript-Logging
!INC BaatScriptLib.JavaScript-ImEx
!INC BaatScriptLib.ImportDataBricksCommon
!INC BaatScriptLib.DiagramAnalysisLayoutCommon

/*
 * This code has been included from the default Diagram Script template.
 * If you wish to modify this template, it is located in the Config\Script Templates
 * directory of your EA install path.
 *
 * Script Name:	ImportDataBricksDALGeneratie
 * Author:		J. de Baat
 * Purpose:		Generate IDB DAL Diagrams for all IDB DAL Objects found on the selected objGlobalIDBDiagram
 * Date:		20-12-2024
 *
 * This script takes a number of selected elements on a diagram to start the analysis.
 * IDBAnalyseDiagram: Analyse the DiagramObjects on this diagram
 *   If the element is a Legend then keep it for global use
 *   If the element contains the DALKeywordsTag then keep it for further processing
 * IDBProcessDALObjects: For each DALKeywordsTag element on the diagram
 *   IDBCheckOrAddPackageDiagram: Add the diagram for this element if it does not exist yet
 *   IDBCheckDALDiagram:
 *     Remove all elements from the diagram except the curElement
 *     Add the global Legend element
 *   DALProcessElement: Add the DAL elements
 * 
 */

// The level to log at
var   BLOGLEVEL = BLOGLEVEL_INFO;		// Choose from: BLOGLEVEL_ERROR, BLOGLEVEL_WARNING, BLOGLEVEL_INFO, BLOGLEVEL_DEBUG, BLOGLEVEL_TRACE

// A set of Maps to contain the different DiagramObjects found
var   arrIDBBRONObjects        = [];		// Array with IDB BRON Objects found in objGlobalIDBDiagram.DiagramObjects
var   arrIDBDALObjects         = [];		// Array with IDB DAL  Objects found in objGlobalIDBDiagram.DiagramObjects
var   objIDBDALLegendObject    = null;		// IDB DAL Legend Object       found in objGlobalIDBDiagram.DiagramObjects
var   objIDBDALLegendElement   = null;		// IDB DAL Legend Element      found in objGlobalIDBDiagram.DiagramObjects

const strAddNewNameDALObject   = "l=30;r=180;t=200;b=250;";
const strAddNewNameLegend      = "l=30;r=180;t=300;b=510;";

const strDiagramHideAttributes = "HideAtts=1;";					// Hides the Attribute compartment of Elements
const strDiagramHideConnLabel  = "HideConnStereotype=1;";		// Hides the Stereotype Labels of Connectors

/*
 * Analyse the DiagramObjects of objGlobalIDBDiagram
 */
function IDBAnalyseDiagram()
{

	var curElement        as EA.Element;
	var curDiagramObject  as EA.DiagramObject;
	var curDiagramObjects as EA.Collection;
	curDiagramObjects      = objGlobalIDBDiagram.DiagramObjects;

	try {

		// Loop over curDiagramObjects to classify the DiagramObjects
		let curDiagramObjectsCount = curDiagramObjects.Count;
		for ( var i = 0 ; i < curDiagramObjectsCount ; i++ )
		{
			curDiagramObject = curDiagramObjects.GetAt( i );

			strMessage = "( " + objGlobalIDBDiagram.Name + " ) found curDiagramObject.ElementID = " + curDiagramObject.ElementID + ",  .ObjectType = " + curDiagramObject.ObjectType + " !!!";
			BLOGTrace( strMessage );

			// Get the curElement from the curDiagramObject.ElementID found
			curElement = GetElementByID( curDiagramObject.ElementID );

			if ( curElement != null ) {
				// Check whether the currentElement is for DiagramAnalysisLayout
				if ( DALIsDiagramAnalysisLayoutElement( curElement ) ) {

					// DAL Element found
					arrIDBDALObjects.push( curElement );
					strMessage = "( " + objGlobalIDBDiagram.Name + " ) found DAL curElement.Name = " + curElement.Name + " (" + curElement.ElementID + ") for Tag = " + curElement.Tag + ", arrIDBDALObjects = " + arrIDBDALObjects.length + " !!!";
					BLOGTrace( strMessage );
				} else {
					// Check whether the currentElement is a Legend
					if ( DALElementIsLegend( curElement ) ) {

						// objIDBDALLegend Element found
						objIDBDALLegendObject  = curDiagramObject;
						objIDBDALLegendElement = curElement;
						strMessage = "( " + objGlobalIDBDiagram.Name + " ) found DAL objIDBDALLegendElement.Name = " + objIDBDALLegendElement.Name + " (" + objIDBDALLegendElement.ElementID + ") for Tag = " + objIDBDALLegendElement.Tag + ", Stereotype = " + objIDBDALLegendElement.Stereotype + " !!!";
						BLOGTrace( strMessage );
						// IDBDumpObject( objIDBDALLegendObject,  "objIDBDALLegendObject."  + objIDBDALLegendObject.ElementID );
						// IDBDumpObject( objIDBDALLegendElement, "objIDBDALLegendElement." + objIDBDALLegendElement.ElementID );
					} else {
						// curElement found is NOT Legend nor DAL Element
						strMessage = "( " + objGlobalIDBDiagram.Name + " ) found NOT Legend nor DAL Element.Name = " + curElement.Name + " (" + curElement.ElementID + ") for Tag = " + curElement.Tag + ", Stereotype = " + curElement.Stereotype + " !!!";
						BLOGTrace( strMessage );
						// IDBDumpObject( curElement, curElement.Name );
					}
				}
			}

		}

		// Show debug message
		if ( objIDBDALLegendElement != null ) {
			strMessage = "( " + objGlobalIDBDiagram.Name + " ) found DAL objIDBDALLegendElement.Name = " + objIDBDALLegendElement.Name + " (" + objIDBDALLegendElement.ElementID + ") and " + arrIDBDALObjects.length + " arrIDBDALObjects!!!";
			BLOGDebug( strMessage );
		} else {
			strMessage = "( " + objGlobalIDBDiagram.Name + " ) found NO DAL objIDBDALLegendElement and " + arrIDBDALObjects.length + " arrIDBDALObjects!!!";
			BLOGDebug( strMessage );
		}

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
		return "IDBAnalyseDiagram catched error " + catch_err.message + "!";
	}

	return "";
}

/*
 * Process the arrIDBDALObjects found when analyzing objGlobalIDBDiagram
 */
function IDBProcessDALObjects()
{

	var curElement        as EA.Element;
	var curDiagramObject  as EA.DiagramObject;
	var curDiagramObjects as EA.Collection;
	var curIDBDALDiagram  as EA.Diagram;
	curDiagramObjects      = objGlobalIDBDiagram.DiagramObjects;

	try {

		// Loop over arrIDBDALObjects to process each of them
		let arrIDBDALObjectsLength = arrIDBDALObjects.length;
		for ( var i = 0 ; i < arrIDBDALObjectsLength ; i++ )
		{

			// Get the curElement from the arrIDBDALObjects array
			curElement = arrIDBDALObjects[i];

			if ( curElement != null ) {
				// Check whether there is a diagram for the curElement
				curIDBDALDiagram = IDBCheckOrAddPackageDiagram( objGlobalIDBPackage, curElement.Name );
				if ( curIDBDALDiagram == null ) {
					strMessage = "( " + curElement.Name + " ) found NO curIDBDALDiagram for " + arrIDBDALObjects.length + " arrIDBDALObjects!!!";
					BLOGError( strMessage );
					strMessage = "IDBAnalyseDiagram could not find or create curIDBDALDiagram for " + curElement.Name + " !";
					return strMessage;
				}
				strMessage = "( " + curIDBDALDiagram.Name + " ) found for curElement.Name = " + curElement.Name + " (" + i + ") of " + arrIDBDALObjects.length + " arrIDBDALObjects!!!";
				BLOGTrace( strMessage );

				// Check the Diagram for Non DAL Elements
				strMessage = IDBCheckDALDiagram( curIDBDALDiagram, curElement );

				// Process the DAL Element on the curIDBDALDiagram as objGlobalDALDiagram;
				objGlobalDALDiagram = curIDBDALDiagram;
				DALProcessElement( curElement );

				BLOGInfo( "Diagram " + curIDBDALDiagram.Name + " ( " + curIDBDALDiagram.DiagramID + " ) is processed at " + _BLOGGetDisplayDate() + "!" );
			}

		}

	} catch (catch_err) {
		BLOGError( " catched error " + catch_err.message + "!" );
		return "IDBAnalyseDiagram catched error " + catch_err.message + "!";
	}

	return "";
}

/*
 * Process the arrIDBDALObjects found when analyzing objGlobalIDBDiagram
 */
function IDBCheckDALDiagram( theDiagram, theElement )
{

	// Cast the input values to objects so we get intellisense
	var curElement        as EA.Element;
	var curDiagram        as EA.Diagram;
	var curDiagramObject  as EA.DiagramObject;
	var curDiagramObjects as EA.Collection;
	var curIDBDALDiagram  as EA.Diagram;

	let boolDALElementFound = false;

	curElement = theElement;
	curDiagram = theDiagram;

	// Only process valid input
	if ( ( curElement != null ) && ( curDiagram != null ) ) {

		curDiagramObjects = curDiagram.DiagramObjects;

		// Loop over curDiagramObjects to delete all except curElement
		let curDiagramObjectsCount = curDiagramObjects.Count;
		for ( var i = curDiagramObjectsCount - 1 ; i >= 0 ; i-- )
		{

			// Get the curElement from the arrIDBDALObjects array
			curDiagramObject = curDiagramObjects.GetAt( i );

			if ( curDiagramObject != null ) {
				// Check whether the curDiagramObject is curElement
				if ( curDiagramObject.ElementID === curElement.ElementID ) {

					boolDALElementFound = true;

					// Skip curElement found
					strMessage = "( " + curDiagram.Name + " ) SKIP DAL curElement.Name = " + curElement.Name + " (" + curElement.ElementID + ") for curDiagramObject: " + curDiagramObject.ElementID + "!!!";
					BLOGTrace( strMessage );
				} else {
					// Remove the curDiagramObject from the diagram
					curDiagramObjects.DeleteAt( i, false );
					strMessage = "( " + curDiagram.Name + " ) DeleteAt Non DAL curDiagramObject: " + curDiagramObject.ElementID + "!!!";
					BLOGTrace( strMessage );
				}
			}

		}

		// Show progress
		curDiagramObjects.Refresh();
		strMessage = "( " + curDiagram.Name + " ) Deleted Non DAL objects except curElement.Name = " + curElement.Name + " (" + curElement.ElementID + ") from curDiagramObjectsCount: " + curDiagramObjectsCount + " to " + curDiagramObjects.Count + "!!!";
		BLOGDebug( strMessage );

		// Add the curElement as DAL Object to curDiagram if not found
		if ( boolDALElementFound === false ) {
			curDiagramObject = curDiagramObjects.AddNew( strAddNewNameDALObject, "" );
			curDiagramObject.ElementID = curElement.ElementID;
			curDiagramObject.Update();
			curDiagramObjects.Refresh();
			strMessage = "( " + curDiagram.Name + " ) Added curElement.Name = " + curElement.Name + " (" + curElement.ElementID + ") with strAddNewNameDALObject: " + strAddNewNameDALObject + "!!!";
			BLOGTrace( strMessage );
		}

		// Add the objIDBDALLegendObject to curDiagram
		curDiagramObject = curDiagramObjects.AddNew( strAddNewNameLegend, "" );
		curDiagramObject.ElementID = objIDBDALLegendElement.ElementID;
		curDiagramObject.Update();
		curDiagramObjects.Refresh();

		strMessage = "( " + curDiagram.Name + " ) Added objIDBDALLegendElement.Name = " + objIDBDALLegendElement.Name + " (" + objIDBDALLegendElement.ElementID + ") with strAddNewNameLegend: " + strAddNewNameLegend + "!!!";
		BLOGTrace( strMessage );
		curDiagram.Update();

		// Set the properties of curDiagram
		curDiagram.HighlightImports = false;		// Hides the Namespace of Elements
		curDiagram.ExtendedStyle    = strDiagramHideAttributes;
		curDiagram.StyleEx          = strDiagramHideConnLabel;
		curDiagram.Update();

		Repository.ReloadDiagram( curDiagram.DiagramID );

	}

	return "";
}

/*
 * Dump a parsed JSON object
 */
function IDBDumpObject( theObject, theObjectName )
{

	try
	{

		BLOGTrace(" Found Attributes of theObject.Name ( " + theObjectName + " )" );
		for ( let key in theObject ) {
			BLOGTrace( "==> theObject.[" + key + "]= " + theObject[key] + " !" );
		}
	}
	catch(catch_err)
	{
		BLOGError("IDBDumpObject found Error: " + catch_err + "!!!" );
		return null;
	}

}

/*
 * Diagram Script main function
 */
function ImportDataBricksDALGeneratie()
{
	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );

	Session.Output( "======================================= Started ImportDataBricksDALGeneratie at " + _BLOGGetDisplayDate() + "!" );

	let curResult = "";

	try
	{

		// Get and check the global variables
		const validDiagram = IDBGetAndCheckDiagram();
		if ( validDiagram ) {

			// Analyse the DiagramObjects of objGlobalIDBDiagram
			if ( curResult.length == 0 ) {
				BLOGInfo( "Diagram( " + objGlobalIDBDiagram.Name + " ) is VALID so proceed processing!" );
				curResult = IDBAnalyseDiagram();
			}

			// Process the arrIDBDALObjects found when analyzing objGlobalIDBDiagram
			if ( curResult.length == 0 ) {
				BLOGInfo( "Diagram( " + objGlobalIDBDiagram.Name + " ) is ANALYSED so proceed processing!" );
				curResult = IDBProcessDALObjects();
			}

			// Handle curResult or Finish processing
			if ( curResult.length > 0 ) {
				BLOGError( curResult );
			} else {
				BLOGInfo( "Finished processing!" );
			}

			// Refresh the objGlobalIDBDiagram using ReloadDiagram
			objGlobalIDBDiagram.Update();
			Repository.ReloadDiagram( objGlobalIDBDiagram.DiagramID );

		} else {
			BLOGError( "Diagram is NOT VALID!" );
		}
	}
	catch(catch_err)
	{
		BLOGError(" found Error: " + catch_err + "!!!" );
	}

	Session.Output( "======================================= Finished ImportDataBricksDALGeneratie at " + _BLOGGetDisplayDate() + "!" );
}

ImportDataBricksDALGeneratie();

//[group=BaatScriptLib]
!INC BaatScriptLib.BaatScript-Logging

/**
 * @file JavaScript-Connector 
 * This script library contains helper functions for working with Connectors. Functions 
 * provided by this module are identified by the prefix CON.
 *
 * @author	J. de Baat, based on JavaScript-TaggedValue by Sparx Systems
 * @date	20-12-2024
 */

/**
 * Retrieves the Connector object from the provided element whose data matches the specified parameters.
 * If the element does not exist, or does not contain a Connector with the specified data, null
 * is returned.
 * NOTE: A Connector is found if the ClientID AND SupplierID and Type are identical.
 *
 * @param[in] theElement (EA.Element) The element to retrieve the Connector value from
 * @param[in] theClientID (String) The ID of the Element registered as Source of the Connector
 * @param[in] theSupplierID (String) The ID of the Element registered as Target of the Connector
 * @param[in] theType (String) The type of the Connector to be found, if empty string, any type will match
 *
 * @return The object of the requested Connector found, null when not found
 */
function CONGetElementConnectorByData( theElement /* : EA.Element */, theClientID /* : ID */, theSupplierID /* : ID */, theType /* : String */ ) /* : EA.Connector */
{

	// Validate input parameters
	if ( ( theElement != null ) && ( theClientID > 0 ) ) {

		// Cast the input values to objects so we get intellisense
		var curElement           as EA.Element;
		var curElementConnectors as EA.Collection;
		var curConnector         as EA.Connector;

		try
		{

			curElement           = theElement;
			curElementConnectors = curElement.Connectors;

			// Check all element Connectors against data to find
			let curElementConnectorsCount = curElementConnectors.Count;
			for ( var i = 0 ; i < curElementConnectorsCount ; i++ )
			{
				curConnector = curElementConnectors.GetAt( i );
				if ( ( curConnector.ClientID   == theClientID ) &&
					 ( curConnector.SupplierID == theSupplierID ) &&
					 ( ( "" === theType ) || ( curConnector.Type == theType ) ) ) 
				{
					// Connector found so clean up memory and return object
					curElementConnectors = null;
					return curConnector;
				}
			}
		}
		catch(catch_err)
		{
			BLOGError("CONGetElementConnectorByData found Error: " + catch_err + "!!!" );
		}

		// Clean up memory
		curElementConnectors = null;
	}

	return null;

}

/**
 * Sets the specified Connector on the provided element. If the provided element does not already
 * contain a Connector with the specified data, a new Connector is created.
 * If a Connector already exists with the specified data then the action is ignored.
 * NOTE: A Connector is found if the ClientID AND SupplierID and Type are identical.
 *
 * @param[in] theElementClient (EA.Element) The element to add the Connector to and registered as Source of the Connector
 * @param[in] theElementSupplier (EA.Element) The element to be registered as Target of the Connector
 * @param[in] theType (String) The type of the Connector to be found, if empty string, any type will match
 * @param[in] skipDuplicate (boolean) If set to true, check for existing connector to prevent duplicate
 *
 * @return The object of the Connector added or found, null in case of error
 */
function CONSetElementConnector( theElementClient /* : EA.Element */, theElementSupplier /* : EA.Element */, theType /* : String */, skipDuplicate /* : Boolean */ ) /* : EA.Connector */
{

	// Validate input parameters
	if ( ( theElementClient != null ) && ( theElementSupplier != null ) && ( theType != "" ) ) {

		// Cast the input values to objects so we get intellisense
		var curElementClient     as EA.Element;
		var curElementSupplier   as EA.Element;
		var curElementConnectors as EA.Collection;
		var curConnector         as EA.Connector;

		const theConnectorDirection = "Unspecified";

		try
		{

			curElementClient   = theElementClient;
			curElementSupplier = theElementSupplier;
			curConnector       = null;

			// Check all Connectors in curElementClient whether the requested Connector already exists
			if ( skipDuplicate ) {
				curConnector   = CONGetElementConnectorByData( curElementClient, curElementClient.ElementID, curElementSupplier.ElementID, theType );
			}

			BLOGTrace("CONSetElementConnector testing Connector between Client(" + curElementClient.ElementID + ") and Supplier(" + curElementSupplier.ElementID + ") for Type " + theType + "!!!" );

			// If curConnector is not found, create a new Connector between curElementClient and curElementSupplier
			if ( curConnector == null )
			{

				curElementConnectors = curElementClient.Connectors;
				curConnector         = curElementConnectors.AddNew( curElementClient.Name, theType );
				curConnector.Update();
				curElementConnectors.Refresh();

				// If curConnector is added, set the attributes
				if ( curConnector != null )
				{
					curConnector.Name       = "";     // Reset the dummy name as needed for AddNew
					curConnector.ClientID   = curElementClient.ElementID;
					curConnector.SupplierID = curElementSupplier.ElementID;
					curConnector.Direction  = theConnectorDirection;
					curConnector.Type       = theType;

					// Commit changes to the Repository
					curConnector.Update();
					curElementConnectors.Refresh();
					curElementClient.Update();
					curElementSupplier.Update();
					BLOGDebug("CONSetElementConnector created new Connector(" + curConnector.ConnectorID + ") between Client(" + curElementClient.ElementID + ") and Supplier(" + curElementSupplier.ElementID + ") for Type " + theType + "!!!" );
					return curConnector;

				} else {
					BLOGError("CONSetElementConnector could NOT create new Connector between Client(" + curElementClient.ElementID + ") and Supplier(" + curElementSupplier.ElementID + ") for Type " + theType + "!!!" );
					return null;
				}
			} else {
				BLOGDebug("CONSetElementConnector skipped create duplicate Connector between Client(" + curElementClient.ElementID + ") and Supplier(" + curElementSupplier.ElementID + ") for Type " + theType + "!!!" );
				return curConnector;
			}

			// Return the curConnector found or added
			BLOGDebug("CONSetElementConnector returns found Connector(" + curConnector.ConnectorID + ") between Client(" + curElementClient.ElementID + ") and Supplier(" + curElementSupplier.ElementID + ") for Type " + theType + "!!!" );
			return curConnector;
		}
		catch(catch_err)
		{
			BLOGError("CONSetElementConnector found Error: " + catch_err + "!!!" );
			return null;
		}

	}

	return null;

}

/**
 * Deletes the specified Connector on the provided element.
 * NOTE: A Connector is found if the ClientID AND SupplierID and Type are identical.
 *
 * @param[in] theConnectorGUID (String) The GUID of the Connector to be deleted
 */
function CONDeleteConnectorByGUID( theConnectorGUID /* : String */ ) /* : void */
{

	// Cast theConnector to EA.Connector so we get intellisense
	var curConnector       as EA.Connector;
	var curElementClient   as EA.Element;
	var curElementSupplier as EA.Element;

	try
	{

		// Find the curConnectorGUID to identify the Connector
		let curConnectorGUID = theConnectorGUID;
		if ( curConnectorGUID == null ) {
			// BLOGTrace( "CONDeleteConnectorByGUID could NOT find curConnectorGUID so NOT deleted!!!");
			return "CONDeleteConnectorByGUID could NOT find curConnectorGUID so NOT deleted!!!";
		}

		// Find the curConnectorGUID
		curConnector = GetConnectorByGuid( curConnectorGUID );
		if ( curConnector == null ) {
			// BLOGTrace( "CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curConnector so NOT deleted!!!");
			return "CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curConnector so NOT deleted!!!";
		}


		// Find and process the source element defined by Start_Object_ID
		let curElementClientID = curConnector.ClientID;
		curElementClient       = GetElementByID( curElementClientID );
		if ( curElementClient == null ) {
			// BLOGTrace("CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curElementClient with curElementClientID = " + curElementClientID + " so NOT deleted!!!" );
			return "CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curElementClient with curElementClientID = " + curElementClientID + " so NOT deleted!!!";
		}

		// Find and process the target element defined by End_Object_ID
		let curElementSupplierID = curConnector.SupplierID;
		curElementSupplier       = GetElementByID( curElementSupplierID );
		if ( curElementSupplier == null ) {
			// BLOGTrace("CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curElementSupplier with curElementSupplierID = " + curElementSupplierID + " so NOT deleted!!!" );
			return "CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curElementSupplier with curElementSupplierID = " + curElementSupplierID + " so NOT deleted!!!";
		}

		// Process the Connector found by curConnectorGUID between curElementClient and curElementSupplier
		// BLOGTrace("CONDeleteConnectorByGUID( " + curConnectorGUID + " ) found curConnector.ConnectorID = " + curConnector.ConnectorID + ", ClientID = " + curConnector.ClientID + ", SupplierID = " + curConnector.SupplierID + "!!!" );
		// Delete the element as part of the curConnector.ClientID
		var curTempConnector   as EA.Connector;
		let curConnectorDeleted = false;
		// Find the index in the curElementClient.Connectors for the curConnector to delete
		let curElementClientConnectorsCount = curElementClient.Connectors.Count;
		for ( let i = 0 ; i < curElementClientConnectorsCount ; i++ ) {
			curTempConnector = curElementClient.Connectors.GetAt( i );
			// BLOGTrace("CONDeleteConnectorByGUID TESTING curElementClient(" + i + ") where curTempConnector.ConnectorID = " + curTempConnector.ConnectorID + "!!!" );
			if ( curTempConnector.ConnectorID == curConnector.ConnectorID ) {
				curElementClient.Connectors.DeleteAt( i, false );
				// BLOGTrace("CONDeleteConnectorByGUID deleted curElementClient(" + i + ") where curConnector.ConnectorID = " + curConnector.ConnectorID + "!!!" );
				curConnectorDeleted = true;
				break; // Stop processing the rest of the Connectors in the for loop
			}
		}

		// Check curConnectorDeleted to commit updates to refresh changes
		if ( curConnectorDeleted ) {
			curElementClient.Connectors.Refresh();
			curElementSupplier.Connectors.Refresh();
		} else {
			// BLOGTrace("CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curElementSupplier with curElementSupplierID = " + curElementSupplierID + " so NOT deleted!!!" );
			return "CONDeleteConnectorByGUID( " + curConnectorGUID + " ) could NOT find curConnector.ConnectorID = " + curConnector.ConnectorID + " within " + curElementClient.Connectors.Count + " curElementClient.Connectors so NOT deleted!!!";
		}
	}
	catch(catch_err)
	{
		BLOGError("CONDeleteConnectorByGUID found Error: " + catch_err + "!!!" );
	}

	return "";
}

//[group=BaatScriptLib]
!INC EAScriptLib.JavaScript-TaggedValue
!INC BaatScriptLib.BaatScript-Logging


/**
 * @file JavaScript-ImEx
 * This script library contains helper functions to assist with IMEX Import and Export of
 * Enterprise Architect Elements and Connectors using an Excel Workbook or CSV file.
 * This functionality is similar to the eaexcelimporter of Geert Bellekens.
 * 
 * Functions in this library are split into three parts: Workbooks, Import and Export.
 * Functions that assist with IMEX Workbooks are prefixed with IMEXW,
 * IMEX Import Functions are prefixed with IMEXI and IMEX Export Functions are prefixed with IMEXE.
 *
 * IMEX Import can be performed by calling the function IMEXIHandleExcelImport().
 * IMEXIHandleExcelImport() requires the name of the WorkSheet containing the information and
 * that the function OnExcelRowImported() is defined in the user's script to be used as a callback
 * whenever row data is read from the IMEX file. The user defined OnExcelRowImported() can query for
 * information about the current row through the functions EXCELIContainsColumn(),
 * EXCELIGetColumnValueByName() and EXCELIGetColumnValueByNumber().
 *
 * To perform an IMEX export, the user must call IMEXEHandleExcelExport() which starts an export
 * session. The call to IMEXEHandleExcelExport() specifies the file name to export to, and the set of
 * columns that will be exported. Once the session has been initialized with a call to
 * IMEXEExportInitialize(), the user may continually call IMEXEExportRow() to export a row to file.
 * Once all rows have been added, the export session is closed by calling IMEXEExportFinalize().
 *
 * @author	J. de Baat, based on JavaScript - CSV by Sparx Systems
 * @date	20-12-2024
 */

const strGlobalEAPackageName        = "ImEx Package";
const strGlobalEADiagramName        = "ImEx Diagram";
const strDefaultElementsFileName    = "ImExElements.xlsx";
const strDefaultConnectorsFileName  = "ImExConnectors.xlsx";
const strDefaultAttributesFileName  = "ImExAttributes.xlsx";
const strDefaultElementsSheetName   = "ImEx_Elements";
const strDefaultConnectorsSheetName = "ImEx_Connectors";
const strDefaultAttributesSheetName = "ImEx_Attributes";
const strTaggedValuesPrefix         = "TAG_";
const strNoClientConnector          = "ImEx_NoClientConnector";

const ImExColumnAttributeName       = "AttributeName";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnAttributeType       = "AttributeType";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnClassGUID           = "CLASSGUID";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnClassType           = "CLASSTYPE";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnConnectorID         = "Connector_ID";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnConnectorGUID       = "CONNECTORGUID";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnConnectorType       = "Connector_Type";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnCTOClassGUID        = "CTO_CLASSGUID";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnCSOClassGUID        = "CSO_CLASSGUID";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnDirection           = "Direction";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnEndObjectID         = "End_Object_ID";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnForeignKey          = "ForeignKey";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnIsCollection        = "IsCollection";		// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnIsOrdered           = "IsOrdered";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnIsStatic            = "IsStatic";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnName                = "Name";				// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnNotes               = "Notes";				// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnLength              = "Length";				// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnPrimaryKey          = "PrimaryKey";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnRouteStyle          = "RouteStyle";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnStartObjectID       = "Start_Object_ID";	// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnStereotype          = "Stereotype";			// Definition of the Column Name used as key for the ImEx Modules
const ImExColumnUnique              = "Unique";				// Definition of the Column Name used as key for the ImEx Modules

const ConnectorRouteStyleDefault    = "3";					// Default for the Column used for the ImEx Modules
const ConnectorStereotypeDefault    = "trace";				// Default for the Column used for the ImEx Modules
const ConnectorTypeDefault          = "Dependency";			// Default for the Column used for the ImEx Modules

const strImExStartPackage           = "Package";
const strImExStartDiagram           = "Diagram";
let   strImExStart                  = "None";

const ConnectorArchiMateAssociation = 0;
const ConnectorArchiMateAggregation = 1;
const ConnectorArchiMateComposition = 2;
const ConnectorDirectionUnspecified = "Unspecified";

const strArchiMatePrefix            = "ArchiMate_";
const strArchiMate3Prefix           = "ArchiMate3::";

/**
 * objGlobalEAPackage needs to have a objGlobalEADiagram and visa versa.
 */
var objGlobalEAPackage as EA.Package;
var objGlobalEADiagram as EA.Diagram;

/**
 * If theValue starts with thePrefix then return value without prefix else return empty string
 *
 * @param[in] theValue (string) The value to test.
 * @param[in] thePrefix (string) The prefix to test against.
 */
function IMEXGGetValueWithoutPrefix( theValue, thePrefix )
{

	try {

		const thePrefixLength = thePrefix.length;
		// BLOGTrace("IMEXGGetValueWithoutPrefix started with thePrefix : " + thePrefix + ", length = " + thePrefixLength + " !" );

		//	If theValue starts with thePrefix then return value without prefix
		if ( theValue.substring( 0, thePrefixLength ).toLowerCase() == thePrefix.toLowerCase() ) {
			// BLOGTrace( "IMEXGGetValueWithoutPrefix found theValue.substring(" + thePrefixLength + ")= " + theValue.substring( thePrefixLength ) + " !" );
			return theValue.substring( thePrefixLength );
		}
	} catch (err) {
		BLOGError( "IMEXGGetValueWithoutPrefix catched error " + err.message + "!" );
		return "";
	}

	return "";

}

/*
 * Check whether theStereotype starts with ArchiMate_ and should be prefixed with ArchiMate3::
 */
function IMEXGCheckArchiMateStereotype( theStereotype )
{

	try {

		let curStereotype = theStereotype;

		// Check whether theStereotype is available
		if ( curStereotype == null ) {
			// BLOGTrace("IMEXGCheckArchiMateStereotype( " + theStereotype + " ) DID NOT update theStereotype to " + curStereotype + "!!!" );
			return curStereotype;
		}

		// Check whether theStereotype should be prefixed
		if ( curStereotype.substring( 0, strArchiMatePrefix.length ).toLowerCase() == strArchiMatePrefix.toLowerCase() ) {
			curStereotype = strArchiMate3Prefix + curStereotype;
			// BLOGTrace("IMEXGCheckArchiMateStereotype( " + theStereotype + " ) updated theStereotype to " + curStereotype + "!!!" );
		} else {
			// BLOGTrace("IMEXGCheckArchiMateStereotype( " + theStereotype + " ) DID NOT update theStereotype to " + curStereotype + "!!!" );
		}

		return curStereotype;

	} catch (err) {
		BLOGError( "IMEXGCheckArchiMateStereotype catched error " + err.message + "!" );
		return theStereotype;
	}
}

/*
 * Check theStereotype to define the ClientEnd.Aggregation
 */
function IMEXGCheckArchiMateStereotypeConnector( theStereotype )
{

	// Check whether theStereotype is available
	if ( theStereotype == null ) {
		return ConnectorArchiMateAssociation;
	}

	// Check what to use as Starting point for export
	switch ( theStereotype ) {
		case "ArchiMate_Aggregation" :
		case "ArchiMate3::ArchiMate_Aggregation" :
		{
			// Set to show as ArchiMate_Aggregation
			return ConnectorArchiMateAggregation;
			break;
		}
		case "ArchiMate_Composition" :
		case "ArchiMate3::ArchiMate_Composition" :
		{
			// Set to show as ArchiMate_Composition
			return ConnectorArchiMateComposition;
			break;
		}
		default:
		{
			// Set to show as default Association
			return ConnectorArchiMateAssociation;
			break;
		}
	}

	return ConnectorArchiMateAssociation;
}

/*
 * Check theStereotype to define the ClientEnd.Aggregation
 */
function IMEXGCheckConnectorDirection( theConnector, theDirection )
{

	try {

		// Cast theConnector to EA.Connector so we get intellisense
		var curConnector       as EA.Connector;
		curConnector            = theConnector;

		// Check whether theConnector and theDirection are available
		if ( ( theConnector == null ) || ( theDirection == null ) ) {
			return;
		}

		// Check whether theConnector and theDirection are equal
		if ( curConnector.Direction == theDirection ) {
			BLOGTrace( "IMEXGCheckConnectorDirection EQUAL curConnector(" + curConnector.ConnectorID + ").Direction= " + curConnector.Direction + ", theDirection= " + theDirection + "!!!" );
			return;
		}

		BLOGTrace( "IMEXGCheckConnectorDirection curConnector(" + curConnector.ConnectorID + ").Direction= " + curConnector.Direction + ", theDirection= " + theDirection + "!!!" );

		// Check what to use as Starting point for export
		switch ( theDirection ) {
			case "Source -> Destination" :
			{
				// Set the SupplierEnd as Navigable
				curConnector.ClientEnd.IsNavigable = false;
				curConnector.ClientEnd.Update();
				curConnector.SupplierEnd.IsNavigable = true;
				curConnector.SupplierEnd.Update();
				break;
			}
			case "Destination -> Source" :
			{
				// Set the ClientEnd as Navigable
				curConnector.ClientEnd.IsNavigable = true;
				curConnector.ClientEnd.Update();
				curConnector.SupplierEnd.IsNavigable = false;
				curConnector.SupplierEnd.Update();
				break;
			}
			case "Bi-Directional" :
			{
				// Set both the ClientEnd and SupplierEnd as Navigable
				curConnector.ClientEnd.IsNavigable = true;
				curConnector.ClientEnd.Update();
				curConnector.SupplierEnd.IsNavigable = true;
				curConnector.SupplierEnd.Update();
				break;
			}
			case "Unspecified" :
			{
				// Set both the ClientEnd and SupplierEnd as Navigable
				curConnector.ClientEnd.IsNavigable = false;
				curConnector.ClientEnd.Update();
				curConnector.SupplierEnd.IsNavigable = false;
				curConnector.SupplierEnd.Update();
				break;
			}
			default:
			{
				// Do nothing
				break;
			}
		}
		curConnector.Update();
		BLOGTrace( "IMEXGCheckConnectorDirection curConnector(" + curConnector.ConnectorID + ").Direction set to " + curConnector.Direction + " based on " + theDirection + ", Navigable: ClientEnd= " + curConnector.ClientEnd.Navigable + ", SupplierEnd= " + curConnector.SupplierEnd.Navigable + "!!!" );

	} catch (err) {
		BLOGError( "IMEXGCheckConnectorDirection catched error " + err.message + "!" );
	}
}

/*
 * Add a new PackageDiagram if it is not defined yet
 */
function IMEXGCheckOrAddPackageDiagram( thePackage, thePackageDiagramName )
{

	try {

		// Validate input parameters
		if ( ( thePackage != null ) && ( thePackageDiagramName != "" ) ) {

			var curPackage  as EA.Package;
			var curDiagrams as EA.Collection;
			var curDiagram  as EA.Diagram;

			// Check all Diagrams in thePackage whether the requested thePackageDiagramName already exists
			curPackage  = thePackage;
			curDiagrams = curPackage.Diagrams;
			curDiagram  = curDiagrams.GetByName( thePackageDiagramName );

			// If curDiagram is not found, create a new diagram
			if ( curDiagram == null )
			{
				// Session.Output( "CheckOrAddPackageDiagram addNew because not found: " + thePackageDiagramName );
				curDiagram = curDiagrams.AddNew( thePackageDiagramName, "Logical" );
				curDiagram.Notes = thePackageDiagramName + " created by JavaScript-ImEx library.";
				curDiagram.Update();

				curDiagrams.Refresh();
				curPackage.Update();

			}

			BLOGTrace( "CheckOrAddPackageDiagram found " + curDiagram.Name + " as part of PackageID=" + thePackage.PackageID + " !" );
			return curDiagram;
		} else {
			BLOGError( "CheckOrAddPackageDiagram could NOT add PackageDiagram " + thePackageDiagramName + "!" );
		}

	} catch (err) {
		BLOGError( "IMEXGCheckOrAddPackageDiagram catched error " + err.message + "!" );
	}

	return null;

}

/*
 * Get and check the global variables
 */
function IMEXGGetAndCheckGlobalVariables()
{

	//	Check objGlobalEAPackage and objGlobalEADiagram
	if ( ( objGlobalEAPackage == null ) && ( objGlobalEADiagram == null ) ) {
		BLOGError( "Either objGlobalEAPackage OR objGlobalEADiagram should be available!" );
		return false;
	}

	//	Check objGlobalEADiagram, get it from objGlobalEAPackage which should not be nothing
	if ( objGlobalEADiagram == null ) {
		objGlobalEADiagram = IMEXGCheckOrAddPackageDiagram( objGlobalEAPackage, strGlobalEADiagramName );
		// BLOGTrace( "GetAndCheckGlobalVariables found " + objGlobalEADiagram.Name + " as part of objGlobalEAPackage " + objGlobalEAPackage.Name + " !" );
	}

	//	Check objGlobalEAPackage, get it from objGlobalEADiagram which should not be nothing
	if ( objGlobalEAPackage == null ) {
		try {
			objGlobalEAPackage = Repository.GetPackageByID( objGlobalEADiagram.PackageID );
			// BLOGTrace( "GetAndCheckGlobalVariables found " + objGlobalEAPackage.Name + " as parent of objGlobalEADiagram " + objGlobalEADiagram.Name + " !" );
		} catch (err) {
			BLOGError( "IMEXGGetAndCheckGlobalVariables catched error " + err.message + "!" );
			objGlobalEAPackage = null;
		}
	}

	//	Check objGlobalEAPackage and objGlobalEADiagram again
	if ( ( objGlobalEAPackage == null ) || ( objGlobalEADiagram == null ) ) {
		BLOGError( "Both objGlobalEAPackage AND objGlobalEADiagram should be available!" );
		return false;
	}

	return true;
}

/*
 * Get and check the global variables for a Project Browser Script
 */
function IMEXGGetAndCheckPackageObject()
{

	// Prepare some global variables
	objGlobalEAPackage = null;
	objGlobalEADiagram = null;

	try {

		// Get the type of element selected in the Project Browser
		let treeSelectedType = Repository.GetTreeSelectedItemType();

		// Handling Code: Uncomment any types you wish this script to support
		// NOTE: You can toggle comments on multiple lines that are currently
		// selected with [CTRL]+[SHIFT]+[C].
		switch ( treeSelectedType )
		{
			case otPackage :
			{
				// Code for when a package is selected
				objGlobalEAPackage = Repository.GetTreeSelectedObject();
				strImExStart = strImExStartPackage;
				BLOGTrace("IMEXGGetAndCheckPackageObject Found Package : " + objGlobalEAPackage.Name + "!" );

				break;
			}
			case otDiagram :
			{
				// Code for when a diagram is selected
				objGlobalEADiagram = Repository.GetTreeSelectedObject();
				strImExStart = strImExStartDiagram;
				BLOGTrace("IMEXGGetAndCheckPackageObject Found Diagram : " + objGlobalEADiagram.Name + "!" );

				break;
			}
			default:
			{
				// Error message
				BLOGError( "This script does not support items of this type." );
				Session.Prompt( "This script does not support items of this type.", promptOK );
				return false;
				break;
			}
		}
	} catch (err) {
		BLOGError( "IMEXGGetAndCheckPackageObject catched error " + err.message + "!" );
		return false;
	}

	// Get and check the global variables
	const  validGlobalVariables = IMEXGGetAndCheckGlobalVariables();
	return validGlobalVariables;

}

/*
 * Get and check the global variables for a Diagram Script
 */
function IMEXGGetAndCheckDiagram()
{

	try {

		// Get a reference to the current diagram
		objGlobalEADiagram = Repository.GetCurrentDiagram();

		if ( objGlobalEADiagram != null )
		{

			// Prepare some global variables
			objGlobalEAPackage = null;
			strImExStart       = strImExStartDiagram;
			BLOGTrace("IMEXGGetAndCheckDiagram Found Diagram : " + objGlobalEADiagram.Name + "!" );

			// Get and check the global variables
			const  validGlobalVariables = IMEXGGetAndCheckGlobalVariables();
			return validGlobalVariables;

		}
		else
		{
			Session.Prompt( "This script requires a diagram to be visible.", promptOK)
		}
	} catch (err) {
		BLOGError( "IMEXGGetAndCheckDiagram catched error " + err.message + "!" );
	}

	return false;

}

