const IDBTaggedValueIDBKey         = "IDBKey";				// Definition of the TV Property used as IDB Key in DataBricks
const IDBTaggedValueIDBConnectorID = "IDBConnectorID";		// Definition of the TV Property used as IDB Key for the Connector ID
const IDBTaggedValueIDBProcessed   = "IDBProcessed";		// Definition of the TV Property used as IDB Processed value in DataBricks
const IDBTaggedValueIDBSource      = "IDBSource";			// Definition of the TV Property used as IDB Key for the Connector Client
const IDBTaggedValueIDBSourceID    = "IDBSourceID";			// Definition of the TV Property used as IDB Key for the Connector Client
const IDBTaggedValueIDBTarget      = "IDBTarget";			// Definition of the TV Property used as IDB Key for the Connector Supplier
const IDBTaggedValueIDBTargetID    = "IDBTargetID";			// Definition of the TV Property used as IDB Key for the Connector Supplier
const IDBTaggedValueIDBStageName   = "Stage";				// Definition of the TV Property used as IDB Processed value in DataBricks

const IDBColumnIDBKey              = strTaggedValuesPrefix + IDBTaggedValueIDBKey;		// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBProcessed        = strTaggedValuesPrefix + IDBTaggedValueIDBProcessed;	// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBSource           = strTaggedValuesPrefix + IDBTaggedValueIDBSource;	// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBSourceID         = strTaggedValuesPrefix + IDBTaggedValueIDBSourceID;	// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBTarget           = strTaggedValuesPrefix + IDBTaggedValueIDBTarget;	// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBTargetID         = strTaggedValuesPrefix + IDBTaggedValueIDBTargetID;	// Definition of the Column Name used as IDB key for the ImEx Modules
const IDBColumnIDBStageName        = strTaggedValuesPrefix + IDBTaggedValueIDBStageName;	// Definition of the Column Name used as IDB key for the ImEx Modules

const IDBKeyPrefix                 = "IDB_";
const IDBKeyElementColumnName      = "Object_ID";			// Definition of the DB Keys to get the Element   IDB key from a TaggedValue
const IDBKeyElementTable           = "t_objectproperties";	// Definition of the DB Keys to get the Element   IDB key from a TaggedValue
const IDBKeyConnectorColumnName    = "ElementID";			// Definition of the DB Keys to get the Connector IDB key from a TaggedValue
const IDBKeyConnectorTable         = "t_connectortag";		// Definition of the DB Keys to get the Connector IDB key from a TaggedValue

const ImExSourceCSV                = "ImExSourceCSV";
const ImExSourceEXCEL              = "ImExSourceEXCEL";

const strTaggedValuesPrefixLength  = strTaggedValuesPrefix.length;

let   strMessage                   = "";
let   strImExSource                = ImExSourceEXCEL;

// Used to create a cache for IDBElementCache
var IDBElementCacheMap             = null;					// : Map   cache for IDBElements
var IDBElementCacheList            = null;					// : Array cache for IDBElements

/**
 * objGlobalIDBPackage needs to have a objGlobalIDBDiagram and visa versa.
 */
var objGlobalIDBPackage as EA.Package;
var objGlobalIDBDiagram as EA.Diagram;

var mapImportColumnTags  = null;			// : Map with tag names found within the column headers

/*
 * Get the TaggedValues columns for the CSV import
 */
function IDBIGetImportColumnTags()
{

	// Only process the CSV columns when ImExSourceCSV and columns not processed yet
	if ( mapImportColumnTags == null ) {
		if ( strImExSource == ImExSourceCSV ) {

			// Create new mapImportColumnTags object to fill
			mapImportColumnTags = new Map();
			var columnName      = "";

			// Process all CSV imported Columns
			let importColumnListLength         = importColumnList.length;
			let strTaggedValuesPrefixLowerCase = strTaggedValuesPrefix.toLowerCase();

			for ( var i = 0 ; i < importColumnListLength ; i++ ) {

				//	If columnName starts with thePrefix then process value without prefix
				columnName = importColumnList[i];
				if ( columnName.substring( 0, strTaggedValuesPrefixLength ).toLowerCase() == strTaggedValuesPrefixLowerCase ) {
					BLOGTrace( " found columnName.substring(" + strTaggedValuesPrefixLength + ")= " + columnName.substring( strTaggedValuesPrefixLength ) + " !" );
					importColumnTag = columnName.substring( strTaggedValuesPrefixLength );
					if ( importColumnTag.length > 0 ) {
						mapImportColumnTags.set( columnName, importColumnTag );
						BLOGTrace( "mapImportColumnTags.set(" + columnName + "," + importColumnTag + ")!!!" );
					}
				}

			}
		}
	}

	return mapImportColumnTags;
}

/*
 * GetColumnValueByName from CSV or EXCEL, depending on the strImExSource
 */
function IDBIGetColumnValueByName( theColumnName )
{

	// Find the curColumnValue identified by theTVName, depending on the strImExSource
	// let curColumnName  = strTaggedValuesPrefix + theTVName;
	let curColumnValue = "";
	if ( strImExSource == ImExSourceCSV ) {
		curColumnValue = CSVIGetColumnValueByName( theColumnName );
	} else {
		curColumnValue = EXCELIGetColumnValueByName( theColumnName );
	}

	// Check whether the curColumnValue is found
	if ( ( curColumnValue == undefined ) || ( curColumnValue == null ) || ( curColumnValue == "" ) ) {
		return null;
	}

	return curColumnValue;
}

/*
 * Find theElement with the GUID information as provided
 */
function IDBFindElementByGUID( theColumnGUID )
{

	var curElement     as EA.Element;
	let curElementGUID  = "";

	// Find and process the Element to be identified by theColumnGUID, depending on the strImExSource
	curElementGUID = IDBIGetColumnValueByName( theColumnGUID );
	if ( curElementGUID == null ) {
		// Return null because not found
		BLOGTrace( " curElementGUID not available !!!" );
		return null;
	}
	curElement     = GetElementByGuid( curElementGUID );
	if ( curElement != null ) {

		// Return curElement found
		strMessage = "( " + curElementGUID + " ) found curElement.Name = " + curElement.Name + " for theColumnGUID " + theColumnGUID + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	//  Nothing found so return null
	strMessage = "( " + curElementGUID + " ) did not find any curElement for theColumnGUID " + theColumnGUID + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Find theConnector with the GUID information as provided
 */
function IDBFindConnectorByGUID( theColumnGUID )
{

	var curConnector     as EA.Connector;
	let curConnectorGUID  = "";

	// Find and process the Connector to be identified by theColumnGUID, depending on the strImExSource
	curConnectorGUID = IDBIGetColumnValueByName( theColumnGUID );
	if ( curConnectorGUID == null ) {
		// Return null because not found
		BLOGTrace( " curConnectorGUID not available !!!" );
		return null;
	}
	curConnector     = GetConnectorByGuid( curConnectorGUID );
	if ( curConnector != null ) {

		// Return curConnector found
		strMessage = "( " + curConnectorGUID + " ) found curConnector.ConnectorID = " + curConnector.ConnectorID + " for theColumnGUID " + theColumnGUID + "!!!";
		BLOGTrace( strMessage );
		return curConnector;
	}

	//  Nothing found so return null
	strMessage = "( " + curConnectorGUID + " ) did not find any curConnector for theColumnGUID " + theColumnGUID + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Get the TaggedValue related to the theTVProperty with value theTVValue from the theTVTable
 */
function IDBGetReferenceIDFromTVProperty( theColumnName, theTVTable, theTVProperty, theTVValue )
{

	// Get the Object_ID registered for theTVProperty with value theTVValue
	let IDBKeyWhereClause   = theTVTable + ".Property = '" + IDBTaggedValueIDBKey + "'"
							+ " and " + theTVTable + ".Value = '" + theTVValue + "'";
	let curReferenceID = IDBGetFieldValueString( theColumnName, theTVTable, IDBKeyWhereClause );
	if ( curReferenceID.length > 0 ) {

		// Return the curReferenceID for curElement found
		strMessage = "( " + theTVValue + " ) found curReferenceID = " + curReferenceID + "!!!";
		BLOGTrace( strMessage );
		return curReferenceID;
	}

	//  Nothing found so return null
	strMessage = "( " + theTVValue + " ) did not find any curReferenceID for theTVProperty " + theTVProperty + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/**
 * Queries the repository database for the first field value whose corresponding row matches the
 * specified WHERE clause.
 *
 * @param[in] columnName (string) The name of the column whose field value will be queried for
 * @param[in] tableName (string) The name of the table that the column resides in
 * @param[in] whereClause (string) The SQL where clause that the query will use to select the
 * appropriate row
 *
 * @return A String representing the requested field value
 */
function IDBGetFieldValueString( columnName /* : String */, tableName /* : String */, whereClause /* : String */ ) /* : String */
{
	var stringValue = "";

	// Construct and execute the querySQL and parse the queryResult
	let querySQL               = "SELECT " + columnName + " FROM " + tableName + " WHERE " + whereClause;
	let queryResult            = Repository.SQLQuery( querySQL );
	let queryResultParts       = queryResult.split( columnName );
	let queryResultPartsLength = queryResultParts.length;

	// BLOGTrace("Repository querySQL = " + querySQL + "!!!" );
	// BLOGTrace("Repository found queryResultPartsLength = " + queryResultPartsLength + ", queryResult = " + queryResult + "!!!" );

	// Check the queryResult for the stringValue found
	if ( queryResultPartsLength == 3 )
	{
		if ( queryResultParts[1].startsWith(">") ) {
			stringValue = queryResultParts[1].substring( 1, ( queryResultParts[1].length - 2 ) );
		}
		strMessage = "Repository found queryResultParts[" + 1 + "] = " + queryResultParts[1] + ", stringValue = " + stringValue + "!!!";
		BLOGTrace( strMessage );
	}

	// Free up memory
	queryResult            = null;
	queryResultParts       = null;
	queryResultPartsLength = null;

	return stringValue;
}

/*
 * Find curElement using the TaggedValue in theTVIDBKey Property
 */
function IDBFindElementByTVIDBKey( theTVIDBKey )
{

	var curElementIndex     = -1;
	var curElement         as EA.Element;
	let curColumnIDBKey     = "";
	let curElementIDBKey    = "";
	let curElementObject_ID = "";

	// Find the Element identified by theTVIDBKey
	curColumnIDBKey  = strTaggedValuesPrefix + theTVIDBKey;
	curElementIDBKey = IDBIGetColumnValueByName( curColumnIDBKey );

	// Find and process the element found by curElementIDBKey from the cache
	curElement = IDBFindElementByTVIDBCache( curElementIDBKey );
	if ( curElement != null ) {
		strMessage = "( " + curElementIDBKey + " ) CACHE found curElement.Name = " + curElement.Name + ", ElementID = " + curElement.ElementID + ", ParentID = " + curElement.ParentID + ", PackageID = " + curElement.PackageID + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	// Find the Element identified by theTVIDBKey
	curElementObject_ID = IDBGetReferenceIDFromTVProperty( IDBKeyElementColumnName, IDBKeyElementTable, theTVIDBKey, curElementIDBKey );
	curElement          = GetElementByID( curElementObject_ID );
	if ( curElement != null ) {
		//  Add curElement to mapIDBElementCache for theTVIDBKeyValue
		curElementIndex = IDBElementCacheMap.size;
		IDBElementCacheList[ curElementIndex ] = curElement;
		IDBElementCacheMap.set( curElementIDBKey, curElementIndex );

		// Return curElement found
		strMessage = "( " + curElementIDBKey + " ) found curElement.Name = " + curElement.Name + " for curElementIDBKey = " + curElementIDBKey + " and curElementObject_ID " + curElementObject_ID + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	//  Nothing found so return null
	strMessage = "( " + theTVIDBKey + " ) did not find curElement for curElementIDBKey = " + curElementIDBKey + " and curElementObject_ID " + curElementObject_ID + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Find curConnector using the TaggedValue in theTVIDBKey Property
 */
function IDBFindConnectorByTVIDBKey( theTVIDBKey )
{

	var curConnector         as EA.Connector;
	let curColumnIDBKey       = "";
	let curConnectorIDBKey    = "";
	let curConnectorElementID = "";

	// Find the Connector identified by theTVIDBKey
	curColumnIDBKey    = strTaggedValuesPrefix + theTVIDBKey;
	curConnectorIDBKey = IDBIGetColumnValueByName( curColumnIDBKey );

	// Find the Connector identified by theTVIDBKey
	curConnectorElementID  = IDBGetReferenceIDFromTVProperty( IDBKeyConnectorColumnName, IDBKeyConnectorTable, theTVIDBKey, curConnectorIDBKey );
	curConnector           = GetConnectorByID( curConnectorElementID );
	if ( curConnector != null ) {

		// Return curConnector found
		strMessage = "( " + curConnectorIDBKey + " ) found curConnector.ConnectorID = " + curConnector.ConnectorID + " for curConnectorIDBKey = " + curConnectorIDBKey + " and curConnectorElementID " + curConnectorElementID + "!!!";
		BLOGTrace( strMessage );
		return curConnector;
	}

	//  Nothing found so return null
	strMessage = "( " + theTVIDBKey + " ) did not find curConnector for curConnectorIDBKey = " + curConnectorIDBKey + " and curConnectorElementID " + curConnectorElementID + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Find curElement using the TaggedValue in theTVIDBKeyValue in the mapIDBElementCache
 */
function IDBFindElementByTVIDBCache( theTVIDBKeyValue )
{

	var curElementIndex  = -1;
	var curElement      as EA.Element;
	curElement           = null;

	// Create the cache if it does not exist yet
	if ( IDBElementCacheMap == null ) {
		IDBElementCacheMap  = new Map();
		IDBElementCacheList = [];
	}

	// Find the Element identified by theTVIDBKeyValue
	if ( IDBElementCacheMap != null && IDBElementCacheMap.has( theTVIDBKeyValue ) ) {
		curElementIndex = IDBElementCacheMap.get( theTVIDBKeyValue );
		curElement      = IDBElementCacheList[ curElementIndex ];
	}

	if ( curElement != null ) {

		// Return curElement found
		strMessage = " found curElement.Name = " + curElement.Name + " for theTVIDBKeyValue = " + theTVIDBKeyValue + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	//  Nothing found so return null
	strMessage = " did not find curElement for theTVIDBKeyValue = " + theTVIDBKeyValue + "!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Find theElement with information as provided
 */
function IDBFindElement( theColumnGUID, theTaggedValueIDBKey )
{

	// Cast theElement to EA.Element so we get intellisense
	var curElement      as EA.Element;

	// Find and process the element found by IDBTaggedValueKeyName
	curElement = IDBFindElementByTVIDBKey( theTaggedValueIDBKey );
	if ( curElement != null ) {
		strMessage = "( " + theTaggedValueIDBKey + " ) found curElement.Name = " + curElement.Name + ", ElementID = " + curElement.ElementID + ", ParentID = " + curElement.ParentID + ", PackageID = " + curElement.PackageID + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	// Find and process the Element to be identified by theColumnGUID
	curElement = IDBFindElementByGUID( theColumnGUID );
	if ( curElement != null ) {
		strMessage = "( " + theColumnGUID + " ) found curElement.Name = " + curElement.Name + ", ElementID = " + curElement.ElementID + ", ParentID = " + curElement.ParentID + ", PackageID = " + curElement.PackageID + "!!!";
		BLOGTrace( strMessage );
		return curElement;
	}

	//  Nothing found so return null
	strMessage = "Did not find curElement for theColumnGUID = " + theColumnGUID + " nor theTaggedValueIDBKey " + theTaggedValueIDBKey + "!!!";
	BLOGTrace( strMessage );
	return null;
}

/*
 * Update the TaggedValues of this Element with information as provided
 */
function IDBISetElementTaggedValues( theElement )
{

	// Cast theElement to EA.Element so we get intellisense
	var curElement  as EA.Element;
	let columnValue  = "";

	curElement = theElement;

	// Only process a valid curElement
	if ( curElement != null ) {

		// Get the list of TaggedValues from the importColumnList
		IDBIGetImportColumnTags();

		// Process the TaggedValues found
		mapImportColumnTags.forEach(function(value, key) {

				// Get and check theGlobalPathPackage
				let curTaggedValue = IDBIGetColumnValueByName( key );
				if ( curTaggedValue != null ) {
					// If curTaggedValue in import, add it to the curElement
					TVSetElementTaggedValue( curElement, value, curTaggedValue, true );
					BLOGTrace( "mapImportColumnTags(" + value + "," + key + ") PROCESSING for curElement " + curElement.Name + "!!!" );
				}
			});

		// Commit the updated values
		curElement.Update();

	}

}

/*
 * Update the TaggedValues of this Connector with information as provided
 */
function IDBISetConnectorTaggedValues( theConnector )
{

	// Cast theElement to EA.Connector so we get intellisense
	var curConnector  as EA.Connector;
	let columnValue  = "";

	curConnector = theConnector;

	// Only process a valid curElement
	if ( curConnector != null ) {

		// Get the list of TaggedValues from the importColumnList
		IDBIGetImportColumnTags();

		// Process the TaggedValues found
		mapImportColumnTags.forEach(function(value, key) {

				// Get and check theGlobalPathPackage
				let curTaggedValue = IDBIGetColumnValueByName( key );
				if ( curTaggedValue != null ) {
					// If curTaggedValue in import, add it to the curElement
					TVSetElementTaggedValue( curConnector, value, curTaggedValue, true );
					BLOGTrace( "mapImportColumnTags(" + value + "," + key + ") PROCESSING for curConnector " + curConnector.Name + "!!!" );
				}
			});

		// Commit the updated values
		curConnector.Update();

	}

}

/*
 * Find theConnector with information as provided
 */
function IDBFindConnector( theColumnGUID, theTaggedValueIDBKey )
{

	// Cast theConnector to EA.Connector so we get intellisense
	var curConnector as EA.Connector;

	// Find and process the element found by IDBTaggedValueKeyName
	curConnector = IDBFindConnectorByTVIDBKey( theTaggedValueIDBKey );
	if ( curConnector != null ) {
		strMessage = "( " + theTaggedValueIDBKey + " ) found ConnectorID = " + curConnector.ConnectorID + ", ClientID = " + curConnector.ClientID + ", SupplierID = " + curConnector.SupplierID + "!!!";
		BLOGTrace( strMessage );
		return curConnector;
	}

	// Find and process the Connector to be identified by theColumnGUID
	curConnector = IDBFindConnectorByGUID( theColumnGUID );
	if ( curConnector != null ) {
		strMessage = "( " + theColumnGUID + " ) found ConnectorID = " + curConnector.ConnectorID + ", ClientID = " + curConnector.ClientID + ", SupplierID = " + curConnector.SupplierID + "!!!";
		BLOGTrace( strMessage );
		return curConnector;
	}

	//  Nothing found so return null
	strMessage = "Did not find curConnector for theColumnGUID = " + theColumnGUID + " nor theTaggedValueIDBKey " + theTaggedValueIDBKey + "!!!";
	BLOGTrace( strMessage );
	return null;
}

/*
 * Get the requested CollectionObject from theCollectionObjects using theObjectName as parameter
 */
function IDBGetCollectionObjectByName( theCollectionObjects, theObjectName )
{
	// Cast theCollectionObjects to EA.Collection so we get intellisense
	var curCollectionObjects as EA.Collection;
	var curCollectionObject  as EA.Element;

	// Check all Elements in theCollectionObjects whether the requested curElement is already defined
	curCollectionObjects = theCollectionObjects;

	// Loop over curCollectionObjects to find theObjectName
	let curCollectionObjectsCount = curCollectionObjects.Count;
	for ( var i = 0 ; i < curCollectionObjectsCount ; i++ )
	{
		curCollectionObject = curCollectionObjects.GetAt( i );
		if ( curCollectionObject.Name === theObjectName ) {
			strMessage = "Found CollectionObject ( " + curCollectionObject.Name + " ) as part of " + curCollectionObjectsCount + " CollectionObjects!!!";
			BLOGTrace( strMessage );

			// Clean up memory
			curCollectionObjects = null;

			return curCollectionObject;
		}
		// strMessage = " TESTED CollectionObject ( " + curCollectionObject.Name + " ) against theObjectName " + theObjectName + " !!!";
		// BLOGTrace( strMessage );
	}

	// Clean up memory
	curCollectionObjects = null;
	curCollectionObject  = null;

	// theObjectName not found as part of curCollectionObjects
	strMessage = "DID NOT FIND theObjectName ( " + theObjectName + " ) as part of " + curCollectionObjectsCount + " CollectionObjects!!!";
	BLOGTrace( strMessage );
	return null;

}

/*
 * Add a new PackageDiagram if it is not defined yet
 */
function IDBCheckOrAddPackageDiagram( thePackage, thePackageDiagramName )
{

	try {

		// Validate input parameters
		if ( ( thePackage != null ) && ( thePackageDiagramName != "" ) ) {

			var curPackage  as EA.Package;
			var curDiagrams as EA.Collection;
			var curDiagram  as EA.Diagram;

			// Check all Diagrams in thePackage whether the requested thePackageDiagramName already exists
			curPackage  = thePackage;
			curDiagrams = curPackage.Diagrams;
			curDiagram  = curDiagrams.GetByName( thePackageDiagramName );

			// If curDiagram is not found, create a new diagram
			if ( curDiagram == null )
			{
				// BLOGTrace( " addNew because not found: " + thePackageDiagramName );
				curDiagram = curDiagrams.AddNew( thePackageDiagramName, "Logical" );
				curDiagram.Notes = thePackageDiagramName + " created by ImportDataBricksCommon library.";
				curDiagram.Update();

				curDiagrams.Refresh();
				curPackage.Update();

			}

			BLOGTrace( " found " + curDiagram.Name + " as part of PackageID=" + thePackage.PackageID + " !" );
			return curDiagram;
		} else {
			BLOGError( " could NOT add PackageDiagram " + thePackageDiagramName + "!" );
		}

	} catch (err) {
		BLOGError( " catched error " + err.message + "!" );
	}

	return null;

}

/*
 * Add a new subpackage if it is not defined yet
 */
function IDBCheckOrAddSubPackage( thePackage, theSubPackageName )
{

	var curPackagePackage  as EA.Package;
	var curPackagePackages as EA.Collection;
	var curSubPackage      as EA.Package;
	curSubPackage           = null;

	// Check all packages in thePackage whether the requested package already exists
	curPackagePackages = thePackage.Packages;
	curSubPackage      = curPackagePackages.GetByName( theSubPackageName );

	// If curSubPackage is not found, create a new theSubPackageName
	if ( curSubPackage == null )
	{
		strMessage = " addNew because not found: " + theSubPackageName;
		BLOGTrace( strMessage );
		curSubPackage       = curPackagePackages.AddNew( theSubPackageName, "Class" );
		curSubPackage.Notes = theSubPackageName + " created by the ImportDataBricksCommonJAVA script on " + _BLOGGetDisplayDate() + ".";
		curSubPackage.Update();

		curPackagePackages.Refresh();

	}

	// Clean up memory
	curPackagePackage  = null;
	curPackagePackages = null;

	strMessage = "Found " + curSubPackage.Name + " as part of PackageID = " + thePackage.PackageID + " !";
	BLOGTrace( strMessage );
	return curSubPackage;

}

/*
 * Get and check the global variables for an IDB Diagram Script
 */
function IDBGetAndCheckDiagram()
{

	// Prepare some global variables
	objGlobalIDBPackage = null;
	objGlobalIDBDiagram = null;

	// Get a reference to the current diagram
	objGlobalIDBDiagram = Repository.GetCurrentDiagram();

	if ( objGlobalIDBDiagram != null )
	{
		strMessage = "Found Diagram : " + objGlobalIDBDiagram.Name + "!";
		BLOGTrace( strMessage );

		// Get a reference to the parent package of the current diagram
		objGlobalIDBPackage = Repository.GetPackageByID( objGlobalIDBDiagram.PackageID );
		strMessage = "Found " + objGlobalIDBPackage.Name + " as parent package of objGlobalIDBDiagram " + objGlobalIDBDiagram.Name + " !";
		BLOGTrace( strMessage );

	}
	else
	{
		Session.Prompt( "This script requires a diagram to be visible.", promptOK)
	}

	//	Check objGlobalIDBPackage and objGlobalIDBDiagram again
	if ( ( objGlobalIDBPackage == null ) || ( objGlobalIDBDiagram == null ) ) {
		BLOGError( "Both objGlobalIDBPackage AND objGlobalIDBDiagram should be available!" );
		return false;
	}

	return true;

}

//[group=BaatScriptLib]
/**
 * @file BaatScript-Logging
 * This script library contains helper functions to assist with logging. Log messages can be 
 * submitted to the various functions in this module, and will be filtered according to the value
 * of BLOGLEVEL.
 *
 * Valid values for BLOGLEVEL are:
 * - BLOGLEVEL_ERROR
 * - BLOGLEVEL_WARNING
 * - BLOGLEVEL_INFO
 * - BLOGLEVEL_DEBUG
 * - BLOGLEVEL_TRACE
 *
 * You can change the log level at any time during execution by setting the BLOGLEVEL variable to the
 * desired value.
 *
 * Functions provided by this module are identified by the prefix BLOG
 *
 * @author	J. de Baat, based on JavaScript-Logging by Sparx Systems
 * @date	20-12-2024
 */

// BLOGLEVEL values
var BLOGLEVEL_ERROR   = 0;
var BLOGLEVEL_WARNING = 1;
var BLOGLEVEL_INFO    = 2;
var BLOGLEVEL_DEBUG   = 3;
var BLOGLEVEL_TRACE   = 4;

// The level to log at
var BLOGLEVEL = BLOGLEVEL_INFO;

/**
 * Logs a message at the ERROR level. The message will be displayed if BLOGLEVEL is set to 
 * BLOGLEVEL_ERROR or above.
 *
 * @param[in] message (String) The message to log
 */
function BLOGError( message /* : String */ ) /* : void */
{
	if ( BLOGLEVEL >= BLOGLEVEL_ERROR ) {
		Session.Output( _BLOGGetDisplayDate() + " [ERROR] " + BLOGError.caller.name + ":: " + message );
	}
}

/**
 * Logs a message at the INFO level. The message will be displayed if BLOGLEVEL is set to 
 * BLOGLEVEL_INFO or above.
 *
 * @param[in] message (String) The message to log
 */
function BLOGInfo( message /* : String */ ) /* : void */
{
	if ( BLOGLEVEL >= BLOGLEVEL_INFO ) {
		Session.Output( _BLOGGetDisplayDate() + " [INFO] " + BLOGInfo.caller.name + ":: " + message );
	}
}

/**
 * Logs a message at the WARNING level. The message will be displayed if BLOGLEVEL is set to 
 * BLOGLEVEL_WARNING or above.
 *
 * @param[in] message (String) The message to log
 */
function BLOGWarning( message /* : String */ ) /* : void */
{
	if ( BLOGLEVEL >= BLOGLEVEL_WARNING ) {
		Session.Output( _BLOGGetDisplayDate() + " [WARNING] " + BLOGWarning.caller.name + ":: " + message );
	}
}

/**
 * Logs a message at the DEBUG level. The message will be displayed if BLOGLEVEL is set to 
 * BLOGLEVEL_DEBUG or above.
 *
 * @param[in] message (String) The message to log
 */
function BLOGDebug( message /* : String */ ) /* : void */
{
	if ( BLOGLEVEL >= BLOGLEVEL_DEBUG ) {
		Session.Output( _BLOGGetDisplayDate() + " [DEBUG] " + BLOGDebug.caller.name + ":: " + message );
	}
}

/**
 * Logs a message at the TRACE level. The message will be displayed if BLOGLEVEL is set to 
 * BLOGLEVEL_TRACE or above.
 *
 * @param[in] message (String) The message to log
 */
function BLOGTrace( message /* : String */ ) /* : void */
{
	if ( BLOGLEVEL >= BLOGLEVEL_TRACE ) {
		Session.Output( _BLOGGetDisplayDate() + " [TRACE] " + BLOGTrace.caller.name + ":: " + message );
	}
}

/**
 * Returns the current date/time in a format suitable for logging.
 *
 * @return A String representing the current date/time
 */
function _BLOGGetDisplayDate() /* : String */
{
	var now = new Date();

	// Pad hour value
	var hours = now.getHours();
	if ( hours < 10 )
		hours = "0" + hours;

	// Pad minute value
	var minutes = now.getMinutes();
	if ( minutes < 10 )
		minutes = "0" + minutes;

	// Pad second value
	var seconds = now.getSeconds();
	if ( seconds < 10 )
		seconds = "0" + seconds;

	var displayDate = now.getFullYear() + "-" + (now.getMonth() + 1) + "-" + now.getDate();
	displayDate += " " + hours + ":" + minutes + ":" + seconds;

	return displayDate;
}

//[group=BaatScriptLib]
!INC Local Scripts.EAConstants-JavaScript
!INC EAScriptLib.JavaScript-Dialog
!INC BaatScriptLib.BaatScript-Logging

/*
 * Script Name:	DiagramAnalysisLayoutCommon
 * Author:		J de Baat
 * Purpose:		Dynamically draw elements on the diagram as indicated by the TaggedValues defined in the selected element
 * Date:		20-12-2024
 *
 * This script takes a number of selected elements on a diagram to start the analysis.
 * For each selected element on a diagram
 *   If the Keywords property of the element contains the DALKeywordsTag
 *     Collect all referenced elements to a set for the first level
 *     Process the current level for all elements in the set:
 *       For each referenced element in the set
 *         If element not yet drawn on the diagram
 *           Draw the element on the indicated location of the diagram
 *           Collect all referenced elements to a set for the next level
 *       Recursively process the set of elements found
 *
 */

// The level to log at
var   BLOGLEVEL = BLOGLEVEL_WARNING;		// Choose from: BLOGLEVEL_ERROR, BLOGLEVEL_WARNING, BLOGLEVEL_INFO, BLOGLEVEL_DEBUG, BLOGLEVEL_TRACE

/*
 * mapDiagramLayoutValues is a map of [Key,Value] to use when generating the analysis diagram
 * Each mapDiagramLayoutValue has a default defined which can be replaced with a value defined as TaggedValue for the selected element
 */
var mapDiagramLayoutValues;

/*
 * mapDALStageLevels is a map of [Key,Value] which contains the number of tables for that particular stage level
 */
var mapDALStageLevels = null;

var objGlobalDALDiagram as EA.Diagram;

const DALDirection     = "DALDirection";			// Whether to analyse in Horizontal (default) or Vertical Direction
const DALNumLevels     = "DALNumLevels";			// Number of levels to analyse
const DALFilter        = "DALFilter";				// Connector TaggedValue to filter what to show
const DALSpaceHor      = "DALSpaceHor";				// Horizontal spacing between elements
const DALSpaceVer      = "DALSpaceVer";				// Vertical spacing between elements
const DALStartHor      = "DALStartHor";				// Horizontal start for elements
const DALStartVer      = "DALStartVer";				// Vertical start for elements
const DALElementWidth  = "DALElementWidth";			// Width of an element to draw
const DALElementHeight = "DALElementHeight";		// Height of an element to draw

const DALTagPrefix     = "DAL";						// String prefix to indicate that this TaggedValue can be used for DiagramAnalysisLayout
const DALFilterNone    = "DALFilterNone";			// Default value to indicate not to use any DALFilter
const DALKeywordsTag   = "diagramanalysislayout";	// String Tag to indicate that this element can be used for DiagramAnalysisLayout
const DALHorizontal    = "Horizontal";				// Analyse in Horizontal (default) Direction
const DALVertical      = "Vertical";				// Analyse in Vertical Direction

const DALTaggedValueStage        = "Stage";			// Definition of the TV Stage property
const DALTaggedValueStageDefault = "DefaultStage";	// Definition of the TV Stage property default value if not defined

/*
 * Create the set of defaults for mapDiagramLayoutValues
 */
function DALCreateDiagramLayoutValues()
{

	try
	{

		// Clean up memory and create a new Map
		mapDiagramLayoutValues = null;
		mapDiagramLayoutValues = new Map();

		mapDiagramLayoutValues.set( DALDirection,     DALHorizontal );
		mapDiagramLayoutValues.set( DALFilter,        DALFilterNone );
		mapDiagramLayoutValues.set( DALNumLevels,     4             );
		mapDiagramLayoutValues.set( DALSpaceHor,      20            );
		mapDiagramLayoutValues.set( DALSpaceVer,      20            );
		mapDiagramLayoutValues.set( DALStartHor,      50            );
		mapDiagramLayoutValues.set( DALStartVer,      100           );
		mapDiagramLayoutValues.set( DALElementWidth,  150           );
		mapDiagramLayoutValues.set( DALElementHeight, 60            );
	}
	catch (catch_err)
	{
		BLOGError("DALCreateDiagramLayoutValues found Error: " + catch_err.message + "!!!" );
	}

}

/*
 * Get the set of values for mapDiagramLayoutValues from the TaggedValues of theElement
 */
function DALGetValuesFromElement( theElement )
{

	// Cast the input values to objects so we get intellisense
	var curElement      as EA.Element;
	var curElementTags  as EA.Collection;
	var curTaggedValue  as EA.TaggedValue;

	try
	{

		curElement     = theElement;
		curElementTags = curElement.TaggedValues;

		// Check all element tags for mapDiagramLayoutValues (starting with "DAL")
		let curElementTagsCount = curElementTags.Count;
		for ( var i = 0 ; i < curElementTagsCount ; i++ )
		{
			curTaggedValue = curElementTags.GetAt( i );
			if ( (curTaggedValue.Name.startsWith( DALTagPrefix )) ) 
			{
				// Get the mapDiagramLayoutValues from the curTaggedValue
				mapDiagramLayoutValues.set( curTaggedValue.Name,   curTaggedValue.Value );
				BLOGTrace("Found curTaggedValue to use for mapDiagramLayoutValues[ " + curTaggedValue.Name + " ] = " + curTaggedValue.Value + " !!!" );
			}
		}
	}
	catch (catch_err)
	{
		BLOGError("DALGetValuesFromElement found Error: " + catch_err.message + "!!!" );
	}

	// Clean up memory
	curElementTags = null;

	return false;

}

/*
 * Get the location of an element based on the parameters
 */
function DALGetElementLocation( numX, numY )
{

	try
	{

		// Calculate the Offset values
		let intOffsetX = numX * ( Number( mapDiagramLayoutValues.get( DALSpaceHor ) ) + Number( mapDiagramLayoutValues.get( DALElementWidth  ) ) );
		let intOffsetY = numY * ( Number( mapDiagramLayoutValues.get( DALSpaceVer ) ) + Number( mapDiagramLayoutValues.get( DALElementHeight ) ) );

		// Create new string from information calculated
		const locL = Number( intOffsetX ) + Number( mapDiagramLayoutValues.get( DALStartHor      ) );
		const locR = Number( locL       ) + Number( mapDiagramLayoutValues.get( DALElementWidth  ) );
		const locT = Number( intOffsetY ) + Number( mapDiagramLayoutValues.get( DALStartVer      ) );
		const locB = Number( locT       ) + Number( mapDiagramLayoutValues.get( DALElementHeight ) );
		const strElementLocation = "l=" + locL + ";r=" + locR + ";t=" + locT + ";b=" + locB + ";";

		return strElementLocation;
	}
	catch (catch_err)
	{
		BLOGError("DALGetElementLocation found Error: " + catch_err.message + "!!!" );
	    return "";
	}

}

/*
 * An element is for DiagramAnalysisLayout when the KeywordsTag contains the string defined by DALKeywordsTag
 */
function DALIsDiagramAnalysisLayoutElement( theElement )
{
	// Cast theElement to EA.Element so we get intellisense
	var curElement as EA.Element;
	curElement      = theElement;

	try
	{
		var strKeywordsTag = curElement.Tag.toLowerCase();
		var idxKeywordsTag = strKeywordsTag.indexOf( DALKeywordsTag );
		return ( idxKeywordsTag >= 0 );
	}
	catch (catch_err)
	{
		BLOGError("DALIsDiagramAnalysisLayoutElement found Error: " + catch_err.message + "!!!" );
	    return false;
	}

    return false;

}

/*
 * Test whether an element is a Legend
 */
function DALElementIsLegend( theElement )
{
	// Cast theElement to EA.Element so we get intellisense
	var inputElement as EA.Element;
	inputElement      = theElement;

	return ( (inputElement.ObjectType == 4) && (inputElement.Subtype == 76) );

}

/*
 * Show the element for DiagramAnalysisLayout when theConnector DALFilter TaggedValue contains the string defined by strDALFilterValue
 */
function DALShowConnector( theConnector )
{
	// Cast theConnector to EA.Connector so we get intellisense
	var curConnector     as EA.Connector;
	var curConnectorTag  as EA.TaggedValue;
	var curConnectorTags as EA.Collection;
	curConnector          = theConnector;

	// Only check when DALFilter defined
	if ( mapDiagramLayoutValues.get( DALFilter ) === DALFilterNone ) {
		return true;
	}

	try
	{

		let strDALFilterValue = mapDiagramLayoutValues.get( DALFilter );
		strDALFilterValue = strDALFilterValue.toLowerCase();

		// Process all curConnectorTags in curConnector
		curConnectorTags = curConnector.TaggedValues;
		let curConnectorTagsCount = curConnectorTags.Count;
		for ( let i = 0 ; i < curConnectorTagsCount ; i++ )
		{
			curConnectorTag  = curConnectorTags.GetAt( i );

			// Test whether value of DALFilter contains the element needed
			if ( (curConnectorTag.Name.startsWith( DALFilter )) ) 
			{
				var curConnectorTagFilter = curConnectorTag.Value.toLowerCase();
				var idxDALFilterValue = curConnectorTagFilter.indexOf( strDALFilterValue );
				if ( idxDALFilterValue >= 0 ) {
					BLOGTrace("DALShowConnector Processed curConnectorTags(" + i + ") of [" + curConnectorTagsCount + "] and curConnectorTag.Name = " + curConnectorTag.Name + "!!!" );
					return true;
				}
			}
		}
		BLOGTrace("DALShowConnector Processed " + curConnectorTagsCount + " curConnectorTags for curConnector.ConnectorID = " + curConnector.ConnectorID + "!!!" );
	}
	catch (catch_err)
	{
		BLOGError("DALShowConnector found Error: " + catch_err.message + "!!!" );
	    return false;
	}

	BLOGDebug("DALShowConnector Processed " + curConnectorTags.Count + " curConnectorTags for curConnector.ConnectorID = " + curConnector.ConnectorID + "!!!" );
    return false;

}

/*
 * Get the requested Element from theCollectionObjects using theElementID as parameter
 */
function DALGetCollectionObjectByID( theCollectionObjects, theElementID )
{
	// Cast theElement to EA.Element so we get intellisense
	var curCollectionObjects as EA.Collection;
	var curCollectionObject  as EA.Element;

	// Check all Elements in theCollectionObjects whether the requested curElement is already defined
	curCollectionObjects = theCollectionObjects;

	try
	{

		// Loop over curCollectionObjects to find theElementID
		let curCollectionObjectsCount = curCollectionObjects.Count;
		for ( var i = 0 ; i < curCollectionObjectsCount ; i++ )
		{
			curCollectionObject = curCollectionObjects.GetAt( i );
			if ( curCollectionObject.ElementID === theElementID ) {
				BLOGTrace( "DALGetCollectionObjectByID found CollectionObject ( " + curCollectionObject.ElementID + " ) as part of " + curCollectionObjectsCount + " CollectionObjects!!!" );
				return curCollectionObject;
			}
			BLOGTrace( "DALGetCollectionObjectByID TESTED CollectionObject ( " + curCollectionObject.ElementID + " ) against theElementID " + theElementID + " !!!" );
		}
	}
	catch (catch_err)
	{
		BLOGError("DALGetCollectionObjectByID found Error: " + catch_err.message + "!!!" );
	    return null;
	}

	// theElementName not found as part of curCollectionObjects
	BLOGDebug( "DALGetCollectionObjectByID DID NOT FIND theElementID ( " + theElementID + " ) as part of CollectionObjects!!!" );
	return null;

}

/*
 * Get the index of theKey contained in theMap
 */
function DALGetMapIndex( theMap, theKey )
{

	try
	{
		let index = 0;
		for (const mapKey of theMap.keys()) {
			// Return the index if the key matches
			if ( mapKey == theKey ) {
				return index;
			}
			index++;
		}
		// Return null if theKey is not found
		return 0;
	}
	catch (catch_err)
	{
		BLOGError("DALGetMapIndex found Error: " + catch_err.message + "!!!" );
	    return 0;
	}

}

/*
 * Get the requested Element from theCollectionObjects using theElementID as parameter
 */
function DALGetElementNewName( theElement )
{
	// Cast theElement to EA.Element so we get intellisense
	var curElement  as EA.Element;
	curElement       = theElement;

	try
	{
		var curElementStageValue  = DALTaggedValueStageDefault;
		var curElementStageObject = curElement.TaggedValues.GetByName( DALTaggedValueStage );
		if ( curElementStageObject != undefined ) {
			curElementStageValue = curElementStageObject.Value;
		}
		BLOGDebug( "DALGetElementNewName found curElementStageValue( " + curElementStageValue + " ) for curElement( " + curElement.Name + " )!!!" );

		// Get the current value for mapDALStageLevels if it exists
		var curElementStageNumbers = 0;
		if ( mapDALStageLevels.has( curElementStageValue ) ) {
			curElementStageNumbers = Number( mapDALStageLevels.get( curElementStageValue ) ) + 1;
		}
		mapDALStageLevels.set( curElementStageValue, curElementStageNumbers );
		var curElementStageIndex = DALGetMapIndex( mapDALStageLevels, curElementStageValue );
		BLOGDebug( "DALGetElementNewName found curElementStageNum[ " + curElementStageValue + " ][ " + curElementStageIndex + " ][ " + curElementStageNumbers + " ] for curElement( " + curElement.Name + " )!!!" );

		// Get the location for the new element depending on DALDirection
		let strDiagramLayout = "";
		if ( mapDiagramLayoutValues.get( DALDirection ) == DALHorizontal ) {
			strDiagramLayout = DALGetElementLocation( curElementStageIndex, curElementStageNumbers );
		} else {
			strDiagramLayout = DALGetElementLocation( curElementStageNumbers, curElementStageIndex );
		}
		BLOGDebug( "DALGetElementNewName found DALGetElementLocation[ " + curElementStageIndex + " ][ " + curElementStageNumbers + " ]: strDiagramLayout( " + strDiagramLayout + " )!!!" );

		return strDiagramLayout;
	}
	catch (catch_err)
	{
		BLOGError("DALGetElementNewName found Error: " + catch_err.message + "!!!" );
	    return "";
	}

}

/*
 * Add the Element indicated by theElementID to the diagram if it is not shown yet
 */
function DALAddElementToDiagram( theDiagram, theElementID )
{

	var curElement        as EA.Element;
	var curDiagram        as EA.Diagram;
	var curDiagramObject  as EA.DiagramObject;
	var curDiagramObjects as EA.Collection;
	var strAddNewName      = "...";

	try
	{

		// Check validity of curElement to be found in the repository by theElementID
		curElement = Repository.GetElementByID( theElementID );
		curDiagram = theDiagram;

		// Only process valid input
		if ( ( curElement == null ) || ( curDiagram == null ) ) {
			return false;
		}

		// Check all Elements in curDiagram whether the requested curElement is already shown
		curDiagramObjects = curDiagram.DiagramObjects;
		curDiagramObject  = DALGetCollectionObjectByID( curDiagramObjects, curElement.ElementID );

		// If curElement is not found on curDiagram, create a new curDiagramObject for it
		if ( curDiagramObject === null )
		{

			// Get the NewName based on the location for the new element
			strAddNewName = DALGetElementNewName( curElement );
			BLOGTrace( "DALAddElementToDiagram addNew because not found: " + curElement.Name + ", strAddNewName(" + strAddNewName + ") as part of Diagram " + curDiagram.Name + "!" );

			curDiagramObject = curDiagramObjects.AddNew( strAddNewName, "" );
			curDiagramObject.ElementID = curElement.ElementID;
			curDiagramObject.Update();
			curDiagramObjects.Refresh();

			curDiagram.Update();
			Repository.ReloadDiagram( curDiagram.DiagramID );

			return true;
		}
	}
	catch (catch_err)
	{
		BLOGError("DALAddElementToDiagram found Error: " + catch_err.message + "!!!" );
	    return false;
	}

	BLOGDebug( "DALAddElementToDiagram found " + curDiagramObject.ElementID + " as already part of curDiagram " + curDiagram.Name + "!" );
	return false;

}

/*
 * Add all elements connected to theElementID to theElementsSet
 */
function DALAddConnectedElementsToSet( theElementsSet, theElementID )
{

	// Cast the input so we get intellisense
	var curElementsSet;
	var curElement as EA.Element;
	curElementsSet  = theElementsSet;

	try
	{

		// Check validity of curElement to be found in the repository by theElementID
		curElement = Repository.GetElementByID( theElementID );
		if ( curElement == null )
		{
			BLOGWarning("DALAddConnectedElementsToSet DID NOT find theElementID(" + theElementID + ") so returns " + curElementsSet.size + " Elements as part of Diagram " + objGlobalDALDiagram.Name + "!!!" );
			return curElementsSet;
		}

		// Process all Elements connected to this Element
		var curElementConnectors as EA.Collection;
		var curConnector         as EA.Connector;
		curElementConnectors      = curElement.Connectors;

		// Check all element Connectors against data to find
		let curElementConnectorsCount = curElementConnectors.Count;
		for ( var i = 0 ; i < curElementConnectorsCount ; i++ )
		{
			curConnector = curElementConnectors.GetAt( i );

			// Check whether to include the element connected to curConnector
			if ( DALShowConnector( curConnector ) ) {

				// Find the newElementID to be on the other end of the Connector
				var newElementID = curConnector.ClientID;
				if ( curConnector.ClientID == curElement.ElementID )
				{
					newElementID = curConnector.SupplierID;
				}

				// Add the newElementID to curElementsSet
				curElementsSet.add( newElementID );
			}
			BLOGTrace("DALAddConnectedElementsToSet curElement(" + curElement.ElementID + "), newElementID=" + newElementID + ", curConnector.ClientID= " + curConnector.ClientID + ", SupplierID= " + curConnector.SupplierID + "!!!" );
		}
	}
	catch (catch_err)
	{
		BLOGError("DALAddConnectedElementsToSet found Error: " + catch_err.message + "!!!" );
	}

	// Clean up memory
	curElementConnectors = null;

	BLOGDebug("DALAddConnectedElementsToSet returns " + curElementsSet.size + " Elements as part of Diagram " + objGlobalDALDiagram.Name + "!!!" );
	return curElementsSet;
}

/*
 * Process theElementsSet for theLevel of DiagramAnalysisLayout
 */
function DALProcessNextLevel( theElementsSet, theLevel )
{

	// Only process when the maximum level not reached yet
	let curLevel = Number( theLevel );
	let maxLevel = Number( mapDiagramLayoutValues.get( DALNumLevels ) );
	if ( curLevel >= maxLevel ) {
		return;
	}
	let nextLevel = Number( theLevel ) + 1;

	try
	{

		// Start new newElementsSet for next level
		let newElementsSet   = new Set();
		let numElementsShown = 0;

		// Add elements to diagram and collect connected elements for next level
		for ( const setElementID of theElementsSet ) {

			// Add element to diagram and move pointer to next location
			if ( DALAddElementToDiagram( objGlobalDALDiagram, setElementID ) ) {
				// Got to next location
				numElementsShown++;
			}

			// Add connected elements to newElementsSet
			newElementsSet = DALAddConnectedElementsToSet( newElementsSet, setElementID );
			BLOGTrace("DALProcessNextLevel[" + theLevel + "]: setElementID = " + setElementID + ", numElementsShown = " + numElementsShown + "!" );

		}

		// Process the newElementsSet for nextLevel of DiagramAnalysisLayout if it contains elements only
		BLOGDebug("DALProcessNextLevel[" + theLevel + "]: processed " + theElementsSet.size + " Elements of which " + numElementsShown + " shown as part of Diagram " + objGlobalDALDiagram.Name + "!!!" );
		if ( newElementsSet.size > 0 ) {
			DALProcessNextLevel( newElementsSet, nextLevel );
		}
	}
	catch (catch_err)
	{
		BLOGError("DALProcessNextLevel found Error: " + catch_err.message + "!!!" );
	}

	// Clean up memory
	newElementsSet = null;

}

/*
 * Process an Element provided as parameter for DiagramAnalysisLayout
 */
function DALProcessElement( theElement )
{

	// Cast theElement to EA.Element so we get intellisense
	var curElement as EA.Element;
	curElement      = theElement;

	try
	{

		mapDALStageLevels = new Map();

		// Create the default values for mapDiagramLayoutValues
		DALCreateDiagramLayoutValues();

		// Check whether the currentElement is for DiagramAnalysisLayout
		if ( DALIsDiagramAnalysisLayoutElement( curElement ) )
		{
			BLOGTrace("DALProcessElement Process curElement(" + curElement.Name + ") for DiagramAnalysisLayout!!!" );

			// Create and get the mapDiagramLayoutValues
			DALGetValuesFromElement( curElement );

			// Get all Elements connected to this Element
			let setDiagramLayoutElements = new Set();
			setDiagramLayoutElements     = DALAddConnectedElementsToSet( setDiagramLayoutElements, curElement.ElementID );

			// Process the setDiagramLayoutElements for DiagramAnalysisLayout first Level
			DALProcessNextLevel( setDiagramLayoutElements, 0 );
			BLOGTrace("DALProcessElement curElement(" + curElement.ElementID + ") processed " + setDiagramLayoutElements.size + " Elements connected to Element(" + curElement.Name + ") for Diagram " + objGlobalDALDiagram.Name + "!!!" );

			// Clean up memory
			setDiagramLayoutElements = null;
			mapDALStageLevels        = null;

		} else {
			BLOGWarning("Element(" + curElement.Name + ") is not for DiagramAnalysisLayout!!!" );
		}
	}
	catch (catch_err)
	{
		BLOGError("DALProcessElement found Error: " + catch_err.message + "!!!" );
	}

}
